window.FACTS = [
  // ---------- Sciences ----------
  { id: "sci-1", theme: "science", title: "L'eau bout plus tôt en montagne",
    text: "Plus on monte, plus la pression de l'air baisse, et plus l'eau bout facilement. Au sommet de l'Everest, elle bout vers 70 °C au lieu de 100 °C : les pâtes y cuisent très mal !" },
  { id: "sci-2", theme: "science", title: "Diamant et mine de crayon : même matière",
    text: "Le diamant et le graphite des crayons sont tous les deux faits uniquement d'atomes de carbone. Seule leur organisation change : en réseau très serré pour le diamant, en feuillets glissants pour le graphite." },
  { id: "sci-3", theme: "science", title: "Les bananes sont (un peu) radioactives",
    text: "Les bananes contiennent beaucoup de potassium, dont une infime partie est du potassium 40, un isotope radioactif. La dose est minuscule et totalement sans danger." },
  { id: "sci-4", theme: "science", title: "Le son est plus rapide dans l'eau",
    text: "Le son voyage à environ 340 m/s dans l'air, mais à près de 1 500 m/s dans l'eau, soit plus de 4 fois plus vite. Les molécules plus serrées transmettent mieux la vibration." },
  { id: "sci-5", theme: "science", title: "Nous partageons 99,9 % de notre ADN",
    text: "Deux êtres humains pris au hasard ont un ADN identique à environ 99,9 %. Toutes nos différences tiennent dans les 0,1 % restants." },
  { id: "sci-6", theme: "science", title: "Un éclair plus chaud que le Soleil",
    text: "Un éclair chauffe l'air autour de lui jusqu'à environ 30 000 °C, soit à peu près 5 fois la température de la surface du Soleil (environ 5 500 °C)." },
  { id: "sci-7", theme: "science", title: "Pourquoi la glace flotte",
    text: "L'eau est une exception : solide, elle est moins dense que liquide. En gelant, ses molécules s'écartent pour former des cristaux. Résultat : la glace flotte, et les lacs gèlent par le dessus, ce qui protège la vie en dessous." },
  { id: "sci-8", theme: "science", title: "Le verre ne coule pas",
    text: "On dit souvent que les vieux vitraux sont plus épais en bas car le verre « coule » lentement. C'est faux : le verre est solide à température ambiante. Les différences d'épaisseur viennent des techniques de fabrication de l'époque." },
  { id: "sci-9", theme: "science", title: "118 éléments chimiques",
    text: "Le tableau périodique compte aujourd'hui 118 éléments. Les quatre derniers (nihonium, moscovium, tennessine et oganesson) ont reçu leur nom officiel en 2016. Ils n'existent que quelques fractions de seconde en laboratoire." },
  { id: "sci-10", theme: "science", title: "Le zéro absolu",
    text: "La température la plus basse possible est le zéro absolu : −273,15 °C. À ce point, les atomes ne pourraient plus perdre d'énergie. En laboratoire, on s'en approche à quelques milliardièmes de degré près, sans jamais l'atteindre." },
  { id: "sci-11", theme: "science", title: "7 fois le tour de la Terre en une seconde",
    text: "La lumière voyage à environ 300 000 km par seconde dans le vide. En une seule seconde, elle pourrait faire à peu près 7,5 fois le tour de la Terre. Rien de ce qui a une masse ne peut aller aussi vite." },
  { id: "sci-12", theme: "science", title: "Marie Curie, deux Nobel",
    text: "Marie Curie est la seule personne à avoir reçu deux prix Nobel dans deux sciences différentes : physique en 1903 et chimie en 1911. Elle a découvert le polonium (nommé en hommage à la Pologne, son pays natal) et le radium." },
  { id: "sci-13", theme: "science", title: "CRISPR, les ciseaux génétiques",
    text: "CRISPR-Cas9 est un outil qui permet de couper et modifier l'ADN avec une grande précision. Ses inventrices, la Française Emmanuelle Charpentier et l'Américaine Jennifer Doudna, ont reçu le prix Nobel de chimie en 2020." },
  { id: "sci-14", theme: "science", title: "L'odeur de la pluie a un nom",
    text: "L'odeur de terre mouillée après une averse s'appelle le pétrichor. Elle vient en partie de la géosmine, une molécule produite par des bactéries du sol. Notre nez y est extrêmement sensible, même à des doses infimes." },
  { id: "sci-15", theme: "science", title: "Le LHC, anneau de 27 km",
    text: "Le plus grand accélérateur de particules du monde, le LHC du CERN, est un anneau de 27 km enterré sous la frontière franco-suisse. En 2012, il a permis de confirmer l'existence du boson de Higgs, la particule liée à la masse." },
  // ---------- Histoire ----------
  { id: "his-1", theme: "histoire", title: "Cléopâtre, plus proche de nous que des pyramides",
    text: "La grande pyramide de Khéops a été bâtie vers 2560 av. J.-C. Cléopâtre est morte en 30 av. J.-C. Elle a donc vécu plus près dans le temps des premiers pas sur la Lune (1969) que de la construction de la pyramide." },
  { id: "his-2", theme: "histoire", title: "La guerre de Cent Ans a duré 116 ans",
    text: "Le conflit entre la France et l'Angleterre s'est étendu de 1337 à 1453, soit 116 ans, avec de longues trêves. Le nom « guerre de Cent Ans » a été donné bien plus tard par les historiens." },
  { id: "his-3", theme: "histoire", title: "Seulement 7 prisonniers à la Bastille",
    text: "Le 14 juillet 1789, quand les Parisiens prennent la Bastille, la forteresse ne détient que 7 prisonniers. Ce sont surtout la poudre et le symbole du pouvoir royal qui étaient visés." },
  { id: "his-4", theme: "histoire", title: "Napoléon n'était pas petit",
    text: "Napoléon mesurait environ 1,69 m, dans la moyenne de son époque. Le mythe vient en partie de la confusion entre le pouce français et le pouce anglais, et de la propagande britannique." },
  { id: "his-5", theme: "histoire", title: "L'imprimerie de Gutenberg",
    text: "Vers 1450, à Mayence, Johannes Gutenberg met au point l'imprimerie à caractères mobiles en métal. Les livres deviennent beaucoup moins chers et les idées circulent bien plus vite en Europe." },
  { id: "his-6", theme: "histoire", title: "La chute du mur de Berlin",
    text: "Le 9 novembre 1989, après 28 ans de séparation, les Berlinois franchissent librement le mur qui coupait leur ville en deux. L'Allemagne est réunifiée moins d'un an plus tard, le 3 octobre 1990." },
  { id: "his-7", theme: "histoire", title: "Les Vikings en Amérique avant Colomb",
    text: "Vers l'an 1000, des Vikings menés par Leif Erikson ont atteint l'Amérique du Nord. Des vestiges de leur campement ont été retrouvés à L'Anse aux Meadows, au Canada, environ 500 ans avant Christophe Colomb." },
  { id: "his-8", theme: "histoire", title: "Les premiers Jeux olympiques",
    text: "Selon la tradition, les Jeux olympiques antiques ont commencé en 776 av. J.-C. à Olympie, en Grèce. Pendant les Jeux, une trêve sacrée permettait aux athlètes de voyager en sécurité." },
  { id: "his-9", theme: "histoire", title: "Le vote des femmes en France",
    text: "Les Françaises ont obtenu le droit de vote par une ordonnance du 21 avril 1944. Elles ont voté pour la première fois en 1945, aux élections municipales. C'est bien après la Nouvelle-Zélande (1893) ou le Royaume-Uni (1918-1928)." },
  { id: "his-10", theme: "histoire", title: "L'esclavage aboli deux fois",
    text: "La France a aboli l'esclavage une première fois en 1794, mais Napoléon l'a rétabli en 1802. L'abolition définitive date de 1848, grâce notamment à Victor Schœlcher." },
  { id: "his-11", theme: "histoire", title: "La peste noire",
    text: "Entre 1347 et 1352, la peste noire a tué entre un tiers et la moitié de la population européenne. La maladie, transmise notamment par les puces des rats, a bouleversé l'économie et la société du Moyen Âge." },
  { id: "his-12", theme: "histoire", title: "La Grande Muraille invisible depuis l'espace",
    text: "Contrairement à la légende, la Grande Muraille de Chine n'est pas visible à l'œil nu depuis l'orbite. Elle est immense en longueur, mais étroite et de la même couleur que le paysage autour." },
  { id: "his-13", theme: "histoire", title: "Le premier vol a duré 12 secondes",
    text: "Le 17 décembre 1903, aux États-Unis, Orville Wright effectue le premier vol motorisé contrôlé de l'histoire. Il dure 12 secondes et couvre environ 37 mètres, soit moins que l'envergure d'un avion de ligne actuel." },
  { id: "his-14", theme: "histoire", title: "Pompéi figée en 79",
    text: "En l'an 79, l'éruption du Vésuve ensevelit la ville romaine de Pompéi sous les cendres. Redécouverte au XVIIIe siècle, elle offre une photographie unique de la vie quotidienne dans l'Empire romain." },
  { id: "his-15", theme: "histoire", title: "Le mètre, enfant de la Révolution",
    text: "Pour remplacer des centaines d'unités locales, la Révolution française crée le système métrique. En 1791, le mètre est défini comme la dix-millionième partie de la distance entre le pôle Nord et l'équateur." },
  // ---------- Espace ----------
  { id: "esp-1", theme: "espace", title: "Sur Vénus, un jour dure plus qu'une année",
    text: "Vénus tourne très lentement sur elle-même : une rotation prend environ 243 jours terrestres. Mais elle fait le tour du Soleil en 225 jours. Son jour est donc plus long que son année !" },
  { id: "esp-2", theme: "espace", title: "La lumière du Soleil a 8 minutes de retard",
    text: "La lumière met environ 8 minutes et 20 secondes pour parcourir les 150 millions de km entre le Soleil et la Terre. Quand tu regardes le Soleil, tu le vois tel qu'il était il y a 8 minutes." },
  { id: "esp-3", theme: "espace", title: "Le plus grand volcan est sur Mars",
    text: "Olympus Mons, sur Mars, s'élève à environ 22 km au-dessus des plaines alentour, soit près de 2,5 fois la hauteur de l'Everest. C'est le plus grand volcan connu du système solaire." },
  { id: "esp-4", theme: "espace", title: "Saturne flotterait sur l'eau",
    text: "Saturne est une géante gazeuse dont la densité moyenne (environ 0,69 g/cm³) est inférieure à celle de l'eau (1 g/cm³). Dans une baignoire assez grande, elle flotterait !" },
  { id: "esp-5", theme: "espace", title: "16 levers de soleil par jour",
    text: "La Station spatiale internationale fait le tour de la Terre en environ 90 minutes, à près de 28 000 km/h. Ses astronautes voient environ 16 levers et 16 couchers de soleil chaque jour." },
  { id: "esp-6", theme: "espace", title: "Des pas éternels sur la Lune",
    text: "Sur la Lune, il n'y a ni vent ni pluie. Les empreintes laissées par les astronautes d'Apollo pourraient rester visibles pendant des millions d'années." },
  { id: "esp-7", theme: "espace", title: "Une cuillère d'étoile à neutrons",
    text: "Une étoile à neutrons concentre plus que la masse du Soleil dans une sphère d'environ 20 km. Une seule cuillère à café de sa matière pèserait des milliards de tonnes." },
  { id: "esp-8", theme: "espace", title: "Jupiter, la géante",
    text: "Jupiter est la plus grosse planète du système solaire : on pourrait y loger plus de 1 300 Terres. Sa Grande Tache rouge est une tempête plus large que notre planète, observée depuis plus de 150 ans." },
  { id: "esp-9", theme: "espace", title: "Le télescope James-Webb",
    text: "Lancé le 25 décembre 2021, le télescope James-Webb observe l'Univers dans l'infrarouge depuis un point situé à 1,5 million de km de la Terre. Il photographie des galaxies formées quelques centaines de millions d'années après le Big Bang." },
  { id: "esp-10", theme: "espace", title: "Plus d'étoiles que de grains de sable",
    text: "On estime que l'Univers observable contient plus d'étoiles que de grains de sable sur toutes les plages de la Terre. Notre galaxie, la Voie lactée, en compte à elle seule entre 100 et 400 milliards." },
  { id: "esp-11", theme: "espace", title: "Retour vers la Lune",
    text: "Avec le programme Artemis, la NASA prépare le retour d'humains sur la Lune, plus de 50 ans après Apollo. La mission Artemis I, sans équipage, a fait le tour de la Lune fin 2022 pour tester la fusée et la capsule." },
  { id: "esp-12", theme: "espace", title: "Sur Mars, le couchant est bleu",
    text: "Sur Mars, le ciel est plutôt ocre le jour, mais les couchers de soleil sont bleutés. La fine poussière martienne diffuse la lumière bleue autour du Soleil quand il est bas sur l'horizon." },
  { id: "esp-13", theme: "espace", title: "Voyager 1, l'objet le plus lointain",
    text: "Lancée en 1977, la sonde Voyager 1 est l'objet fabriqué par l'humain le plus éloigné de la Terre : plus de 24 milliards de km. Elle a quitté la bulle protectrice du Soleil en 2012 et emporte un disque d'or avec des sons de la Terre." },
  { id: "esp-14", theme: "espace", title: "La Lune s'éloigne",
    text: "La Lune s'éloigne de la Terre d'environ 3,8 cm par an, à peu près la vitesse de pousse de nos ongles. On le mesure grâce à des réflecteurs laissés sur la Lune par les missions Apollo." },
  { id: "esp-15", theme: "espace", title: "Une année de 88 jours",
    text: "Mercure, la planète la plus proche du Soleil, en fait le tour en seulement 88 jours terrestres. Sans véritable atmosphère, ses températures varient d'environ 430 °C le jour à −180 °C la nuit." },
  // ---------- Animaux ----------
  { id: "ani-1", theme: "animaux", title: "La pieuvre a trois cœurs",
    text: "La pieuvre possède trois cœurs : deux envoient le sang vers les branchies, le troisième vers le reste du corps. Son sang est bleu, car il transporte l'oxygène grâce à du cuivre (l'hémocyanine) et non du fer." },
  { id: "ani-2", theme: "animaux", title: "Les flamants roses naissent gris",
    text: "Les flamants ne sont pas roses à la naissance. Leur couleur vient des pigments (caroténoïdes) contenus dans les petites crevettes et les algues qu'ils mangent." },
  { id: "ani-3", theme: "animaux", title: "Les dauphins dorment à moitié",
    text: "Les dauphins doivent remonter respirer à la surface consciemment. Pour dormir, ils mettent au repos une moitié de leur cerveau à la fois, pendant que l'autre reste vigilante." },
  { id: "ani-4", theme: "animaux", title: "Le plus grand animal de tous les temps",
    text: "La baleine bleue peut dépasser 30 m de long et 150 tonnes. C'est le plus grand animal ayant jamais existé, plus grand que tous les dinosaures connus. Son cœur pèse à lui seul environ 180 kg." },
  { id: "ani-5", theme: "animaux", title: "La danse des abeilles",
    text: "Pour indiquer une source de nourriture, l'abeille exécute une « danse frétillante » dans la ruche. L'angle de la danse indique la direction par rapport au Soleil, et sa durée la distance." },
  { id: "ani-6", theme: "animaux", title: "Le koala, champion de la sieste",
    text: "Le koala dort jusqu'à 20 heures par jour. Les feuilles d'eucalyptus dont il se nourrit sont pauvres en énergie et difficiles à digérer : il économise ses forces." },
  { id: "ani-7", theme: "animaux", title: "Le guépard, sprinteur absolu",
    text: "Le guépard est l'animal terrestre le plus rapide : il peut dépasser 100 km/h en quelques secondes. Mais il s'épuise vite et ne tient cette vitesse que sur quelques centaines de mètres." },
  { id: "ani-8", theme: "animaux", title: "Les corbeaux reconnaissent les visages",
    text: "Des chercheurs ont montré que les corbeaux reconnaissent les visages humains et s'en souviennent pendant des années. Ils peuvent même « prévenir » leurs congénères d'une personne jugée dangereuse." },
  { id: "ani-9", theme: "animaux", title: "Le tardigrade, quasi indestructible",
    text: "Le tardigrade, animal de moins d'un millimètre, survit à la déshydratation totale, au froid extrême et même au vide spatial. Il se met en « pause » en remplaçant presque toute son eau, puis se réveille quand les conditions redeviennent favorables." },
  { id: "ani-10", theme: "animaux", title: "L'axolotl repousse",
    text: "L'axolotl, une salamandre du Mexique, peut régénérer ses pattes, sa queue, et même des parties de son cœur et de son cerveau. Les chercheurs l'étudient pour comprendre la régénération des tissus." },
  { id: "ani-11", theme: "animaux", title: "Les éléphants se reconnaissent",
    text: "Les éléphants se reconnaissent dans un miroir, signe rare de conscience de soi. Ils communiquent aussi par des infrasons, trop graves pour notre oreille, qui portent sur plusieurs kilomètres." },
  { id: "ani-12", theme: "animaux", title: "Le paresseux descend une fois par semaine",
    text: "Le paresseux passe presque toute sa vie dans les arbres. Il n'en descend qu'environ une fois par semaine, pour faire ses besoins au pied du tronc. Son métabolisme est si lent qu'il digère un repas en plusieurs semaines." },
  { id: "ani-13", theme: "animaux", title: "Le requin du Groenland, 400 ans",
    text: "Le requin du Groenland est le vertébré qui vit le plus longtemps connu : plus de 250 ans, et peut-être près de 400. Il grandit d'environ 1 cm par an dans les eaux glacées de l'Arctique." },
  { id: "ani-14", theme: "animaux", title: "Les chats ne sentent pas le sucré",
    text: "Les chats ne perçoivent pas le goût sucré : le gène de leur récepteur au sucre est inactif. Carnivores stricts, ils n'en ont pas besoin. Leur attirance pour certains aliments vient du gras ou des protéines." },
  { id: "ani-15", theme: "animaux", title: "Le manchot empereur, papa poule",
    text: "Chez le manchot empereur, c'est le mâle qui couve l'œuf, posé sur ses pattes sous un repli de peau, pendant environ deux mois de l'hiver antarctique, à −40 °C et sans manger. Les mâles se serrent en groupe pour garder la chaleur." },
  // ---------- Corps humain ----------
  { id: "cor-1", theme: "corps", title: "Un bébé a plus d'os qu'un adulte",
    text: "Un adulte possède 206 os. Un nouveau-né en a environ 300 : beaucoup fusionnent pendant la croissance, comme ceux du crâne." },
  { id: "cor-2", theme: "corps", title: "Le plus petit os est dans l'oreille",
    text: "L'étrier, situé dans l'oreille moyenne, mesure environ 3 mm. C'est le plus petit os du corps humain. Il transmet les vibrations du son vers l'oreille interne." },
  { id: "cor-3", theme: "corps", title: "Le cerveau, gros consommateur",
    text: "Le cerveau représente environ 2 % du poids du corps, mais il consomme près de 20 % de son énergie. Penser coûte cher !" },
  { id: "cor-4", theme: "corps", title: "Des empreintes uniques, même chez les jumeaux",
    text: "Les vrais jumeaux ont le même ADN, mais pas les mêmes empreintes digitales. Celles-ci se forment dans le ventre de la mère et dépendent de minuscules variations de pression et de position." },
  { id: "cor-5", theme: "corps", title: "100 000 battements par jour",
    text: "Au repos, le cœur bat environ 60 à 80 fois par minute, soit près de 100 000 fois par jour et plus de 2,5 milliards de fois au cours d'une vie." },
  { id: "cor-6", theme: "corps", title: "Impossible de se chatouiller soi-même",
    text: "Quand tu bouges, ton cerveau (notamment le cervelet) prédit la sensation que tu vas ressentir et l'atténue. Sans effet de surprise, pas de chatouilles !" },
  { id: "cor-7", theme: "corps", title: "Les ongles des mains poussent plus vite",
    text: "Les ongles des mains poussent environ 3 à 4 fois plus vite que ceux des pieds, à peu près 3 mm par mois. Ils poussent aussi plus vite sur la main que tu utilises le plus." },
  { id: "cor-8", theme: "corps", title: "L'estomac se protège de son propre acide",
    text: "L'acide de l'estomac est assez fort pour attaquer le métal. Pour ne pas se digérer lui-même, l'estomac se tapisse d'un mucus protecteur et renouvelle les cellules de sa paroi en quelques jours." },
  { id: "cor-9", theme: "corps", title: "Autant de bactéries que de cellules",
    text: "Notre corps contient environ 38 000 milliards de bactéries, à peu près autant que de cellules humaines. L'ancien chiffre de « dix fois plus de bactéries » a été corrigé par une étude de 2016." },
  { id: "cor-10", theme: "corps", title: "Le deuxième cerveau",
    text: "L'intestin contient environ 200 millions de neurones, d'où son surnom de « deuxième cerveau ». Il communique en permanence avec le cerveau et influence la digestion, mais aussi l'humeur." },
  { id: "cor-11", theme: "corps", title: "2 millions de globules par seconde",
    text: "Un globule rouge vit environ 120 jours. Pour les remplacer, la moelle osseuse en fabrique environ 2 millions chaque seconde." },
  { id: "cor-12", theme: "corps", title: "Perdre ses cheveux, c'est normal",
    text: "Perdre entre 50 et 100 cheveux par jour est tout à fait normal. Chaque cheveu suit un cycle : il pousse pendant plusieurs années, se repose, puis tombe pour laisser place à un nouveau." },
  { id: "cor-13", theme: "corps", title: "Un million de couleurs",
    text: "L'œil humain peut distinguer environ un million de nuances de couleurs grâce à trois types de cônes, sensibles au rouge, au vert et au bleu. Certaines personnes, plus rares, en ont quatre." },
  { id: "cor-14", theme: "corps", title: "Le foie repousse",
    text: "Le foie est capable de se régénérer : après l'ablation d'une grande partie de l'organe, il peut retrouver sa taille en quelques semaines ou mois. C'est ce qui permet les greffes à partir d'un donneur vivant." },
  { id: "cor-15", theme: "corps", title: "Le bâillement est contagieux",
    text: "Voir, entendre ou même lire le mot « bâiller » peut déclencher un bâillement. Ce phénomène contagieux est plus fort entre proches, et des études montrent que les chiens peuvent même « attraper » les bâillements de leur maître." },
  // ---------- Géographie ----------
  { id: "geo-1", theme: "geo", title: "La France, record des fuseaux horaires",
    text: "Grâce à ses territoires d'outre-mer (Polynésie, Réunion, Guyane, Nouvelle-Calédonie…), la France couvre 12 fuseaux horaires. C'est le record mondial, devant la Russie et les États-Unis." },
  { id: "geo-2", theme: "geo", title: "Le lac Baïkal, réservoir géant",
    text: "En Sibérie, le lac Baïkal est le plus profond du monde (1 642 m) et contient environ 20 % de l'eau douce liquide en surface de la planète. Il est aussi l'un des plus anciens : environ 25 millions d'années." },
  { id: "geo-3", theme: "geo", title: "L'Australie est plus large que la Lune",
    text: "La Lune mesure environ 3 470 km de diamètre. L'Australie, elle, s'étend sur près de 4 000 km d'est en ouest. Elle est donc plus large que la Lune !" },
  { id: "geo-4", theme: "geo", title: "Le plus grand désert est glacé",
    text: "Un désert se définit par le manque de précipitations, pas par la chaleur. Avec ses 14 millions de km², l'Antarctique est le plus grand désert du monde, devant le Sahara." },
  { id: "geo-5", theme: "geo", title: "Le Canada, roi des côtes",
    text: "Avec ses milliers d'îles et de fjords, le Canada possède le plus long littoral du monde : plus de 200 000 km de côtes, soit environ 5 fois le tour de la Terre." },
  { id: "geo-6", theme: "geo", title: "L'Everest n'est pas le plus proche des étoiles",
    text: "La Terre est légèrement renflée à l'équateur. Du coup, le sommet du Chimborazo, en Équateur, est le point le plus éloigné du centre de la Terre, même si l'Everest est le plus haut au-dessus du niveau de la mer." },
  { id: "geo-7", theme: "geo", title: "Istanbul, entre deux continents",
    text: "Istanbul est coupée en deux par le détroit du Bosphore : une partie de la ville est en Europe, l'autre en Asie. On peut changer de continent en quelques minutes de ferry." },
  { id: "geo-8", theme: "geo", title: "Le Nil coule vers le nord",
    text: "Le Nil, l'un des deux plus longs fleuves du monde avec l'Amazone, prend sa source en Afrique de l'Est et coule du sud vers le nord jusqu'à la Méditerranée, sur plus de 6 600 km." },
  { id: "geo-9", theme: "geo", title: "L'Inde, pays le plus peuplé",
    text: "Selon l'ONU, l'Inde est devenue en 2023 le pays le plus peuplé du monde, devant la Chine, avec plus de 1,4 milliard d'habitants. La population chinoise, elle, a commencé à diminuer." },
  { id: "geo-10", theme: "geo", title: "Le Vatican, plus petit État du monde",
    text: "Avec environ 0,44 km², le Vatican est le plus petit État du monde, enclavé dans la ville de Rome. Il compte quelques centaines d'habitants seulement." },
  { id: "geo-11", theme: "geo", title: "La Russie, plus grande que Pluton",
    text: "Avec environ 17 millions de km², la Russie est le plus grand pays du monde. Sa superficie dépasse même la surface totale de la planète naine Pluton, d'environ 16,7 millions de km²." },
  { id: "geo-12", theme: "geo", title: "Combien de pays dans le monde ?",
    text: "On compte généralement 195 pays : les 193 États membres de l'ONU, plus le Vatican et la Palestine, qui ont le statut d'observateurs. Mais certains territoires, comme Taïwan ou le Kosovo, ne sont pas reconnus par tous." },
  { id: "geo-13", theme: "geo", title: "On flotte sur la mer Morte",
    text: "La mer Morte, entre Israël et la Jordanie, est le point le plus bas des terres émergées, à environ 430 m sous le niveau de la mer. Son eau est environ 10 fois plus salée que l'océan : on y flotte sans effort." },
  { id: "geo-14", theme: "geo", title: "La plus longue frontière de la France",
    text: "La plus longue frontière terrestre de la France n'est pas avec l'Espagne ou la Belgique, mais avec le Brésil : environ 730 km, entre la Guyane et l'État brésilien de l'Amapá." },
  { id: "geo-15", theme: "geo", title: "Le mont Blanc change de taille",
    text: "Le mont Blanc, plus haut sommet d'Europe occidentale, culmine à environ 4 806 m. Sa hauteur exacte varie d'une mesure à l'autre selon l'épaisseur de la calotte de neige et de glace au sommet." },
  // ---------- Arts & culture ----------
  { id: "art-1", theme: "art", title: "Le vol qui a rendu la Joconde célèbre",
    text: "En 1911, Vincenzo Peruggia, un ancien employé du Louvre, vole la Joconde. Elle n'est retrouvée qu'en 1913 en Italie. L'affaire, très médiatisée, a fait d'elle le tableau le plus célèbre du monde." },
  { id: "art-2", theme: "art", title: "Van Gogh, presque aucune vente",
    text: "Vincent van Gogh a peint plus de 850 tableaux, mais on ne lui connaît qu'une seule vente certaine de son vivant : « La Vigne rouge », en 1890. Aujourd'hui, ses toiles valent des dizaines de millions." },
  { id: "art-3", theme: "art", title: "La statue de la Liberté est française",
    text: "Offerte par la France aux États-Unis en 1886, la statue de la Liberté a été sculptée par Auguste Bartholdi. Sa structure métallique intérieure a été conçue par Gustave Eiffel." },
  { id: "art-4", theme: "art", title: "Beethoven, compositeur sourd",
    text: "Beethoven a commencé à perdre l'ouïe vers 30 ans. Quand il compose sa 9e symphonie, avec le célèbre « Hymne à la joie », il est presque totalement sourd. Il l'entendait dans sa tête." },
  { id: "art-5", theme: "art", title: "Les statues grecques étaient colorées",
    text: "Les sculptures grecques antiques que l'on voit blanches dans les musées étaient à l'origine peintes de couleurs vives. Les pigments ont disparu avec le temps, mais des analyses en retrouvent des traces." },
  { id: "art-6", theme: "art", title: "Le Penseur devait être Dante",
    text: "Rodin a d'abord imaginé « Le Penseur » pour le sommet de sa « Porte de l'Enfer », inspirée de la Divine Comédie. La figure représentait le poète Dante contemplant son œuvre." },
  { id: "art-7", theme: "art", title: "Le ballet parle français",
    text: "Le ballet est né dans les cours italiennes de la Renaissance, puis a été codifié en France sous Louis XIV, grand danseur lui-même. C'est pourquoi, partout dans le monde, les pas ont des noms français : plié, jeté, pirouette…" },
  { id: "art-8", theme: "art", title: "Le Cri existe en plusieurs versions",
    text: "Edvard Munch a réalisé plusieurs versions du « Cri » entre 1893 et 1910 : peintures, pastels et lithographies. Une version au pastel s'est vendue près de 120 millions de dollars en 2012." },
  { id: "art-9", theme: "art", title: "Notre-Dame a rouvert",
    text: "Ravagée par un incendie le 15 avril 2019, la cathédrale Notre-Dame de Paris a rouvert ses portes le 7 décembre 2024, après plus de cinq ans de travaux menés par près de 2 000 artisans et compagnons." },
  { id: "art-10", theme: "art", title: "Monet et ses Nymphéas",
    text: "Claude Monet a peint environ 250 toiles de nymphéas, inspirées de son jardin d'eau à Giverny. Huit grands panneaux sont exposés au musée de l'Orangerie, à Paris, dans des salles conçues selon ses souhaits." },
  { id: "art-11", theme: "art", title: "Le Louvre, musée le plus visité",
    text: "Le Louvre est le musée le plus visité au monde, avec près de 9 millions de visiteurs par an. Il conserve plus de 35 000 œuvres exposées, et il faudrait des semaines pour toutes les voir." },
  { id: "art-12", theme: "art", title: "La tour Eiffel devait disparaître",
    text: "Construite pour l'Exposition universelle de 1889, la tour Eiffel devait être démontée au bout de 20 ans. Elle a été sauvée grâce à son utilité pour les antennes de radio et de télégraphie sans fil." },
  { id: "art-13", theme: "art", title: "L'œuvre de Banksy qui s'autodétruit",
    text: "En 2018, juste après sa vente aux enchères à Londres pour plus d'un million de livres, l'œuvre « Girl with Balloon » de Banksy s'est en partie déchiquetée grâce à une broyeuse cachée dans le cadre. Renommée, elle a ensuite pris encore plus de valeur." },
  { id: "art-14", theme: "art", title: "Frida Kahlo et ses autoportraits",
    text: "Après un grave accident de bus à 18 ans, Frida Kahlo commence à peindre alitée, avec un miroir au-dessus de son lit. Sur environ 200 œuvres, une cinquantaine sont des autoportraits." },
  { id: "art-15", theme: "art", title: "Le Radeau de la Méduse, fait divers réel",
    text: "Le célèbre tableau de Théodore Géricault (1819) représente un vrai naufrage : celui de la frégate La Méduse en 1816. Sur environ 150 personnes entassées sur un radeau, seule une quinzaine a survécu." },
  // ---------- Mots & langues ----------
  { id: "mot-1", theme: "mots", title: "« OK » est né d'une blague",
    text: "En 1839, des journaux de Boston s'amusaient à abréger des fautes volontaires. « OK » signifiait « oll korrect », une façon farfelue d'écrire « all correct ». Le mot a ensuite conquis le monde." },
  { id: "mot-2", theme: "mots", title: "« Robot » veut dire « travail »",
    text: "Le mot « robot » a été popularisé en 1920 par la pièce de théâtre de l'écrivain tchèque Karel Čapek. Il vient du tchèque « robota », qui signifie travail forcé, corvée." },
  { id: "mot-3", theme: "mots", title: "Le « salaire » et le sel",
    text: "Le mot « salaire » vient du latin « salarium », dérivé de « sal », le sel. Le sel était précieux dans l'Antiquité : il servait à conserver les aliments." },
  { id: "mot-4", theme: "mots", title: "Des mots venus de l'arabe",
    text: "Le français a emprunté beaucoup de mots à l'arabe, souvent au Moyen Âge via les sciences : algèbre, alcool, chiffre, zéro, sucre, café ou encore magasin." },
  { id: "mot-5", theme: "mots", title: "La « quarantaine » : 40 jours",
    text: "Aux XIVe et XVe siècles, pour se protéger de la peste, des ports comme Venise imposaient aux navires d'attendre 40 jours avant de débarquer. De l'italien « quaranta giorni » est née la « quarantaine »." },
  { id: "mot-6", theme: "mots", title: "Un mot de 25 lettres",
    text: "« Anticonstitutionnellement », avec ses 25 lettres, est souvent cité comme le plus long mot courant du dictionnaire français." },
  { id: "mot-7", theme: "mots", title: "En mandarin, le ton change le sens",
    text: "Le mandarin est une langue tonale : la même syllabe change de sens selon l'intonation. « Mā » (ton plat) veut dire mère, alors que « mǎ » (ton descendant puis montant) veut dire cheval." },
  { id: "mot-8", theme: "mots", title: "Le français sur les cinq continents",
    text: "Le français est langue officielle dans 29 pays et parlé par plus de 300 millions de personnes. La majorité des francophones vivent aujourd'hui en Afrique." },
  { id: "mot-9", theme: "mots", title: "« Emoji » n'a rien à voir avec émotion",
    text: "Le mot emoji vient du japonais : « e » (image) et « moji » (caractère). Sa ressemblance avec le mot « émotion » est une pure coïncidence. Les premiers emojis ont été créés au Japon à la fin des années 1990." },
  { id: "mot-10", theme: "mots", title: "Chocolat et tomate, des mots aztèques",
    text: "Les mots chocolat et tomate viennent du nahuatl, la langue des Aztèques (« xocolatl » et « tomatl »). Ils sont arrivés en Europe au XVIe siècle par l'espagnol, avec les produits eux-mêmes." },
  { id: "mot-11", theme: "mots", title: "Les Immortels de l'Académie",
    text: "Fondée en 1635 par le cardinal de Richelieu, l'Académie française compte 40 membres élus à vie, surnommés les « Immortels ». Sa mission : veiller sur la langue et rédiger son dictionnaire." },
  { id: "mot-12", theme: "mots", title: "« Merci », un mot de marchand",
    text: "Le mot « merci » vient du latin « merces », qui signifiait salaire, récompense. Au Moyen Âge, il désignait la grâce qu'on accorde, comme dans « être à la merci de quelqu'un »." },
  { id: "mot-13", theme: "mots", title: "L'anglais parle français",
    text: "Après la conquête de l'Angleterre par Guillaume le Conquérant en 1066, le français est devenu la langue de la cour anglaise pendant trois siècles. Résultat : près d'un tiers du vocabulaire anglais vient du français." },
  { id: "mot-14", theme: "mots", title: "Le basque, une langue mystère",
    text: "Le basque est un isolat : on ne lui connaît aucun lien de parenté avec une autre langue vivante. Il était déjà parlé avant l'arrivée des langues indo-européennes comme le latin." },
  { id: "mot-15", theme: "mots", title: "7 000 langues dans le monde",
    text: "Il existe environ 7 000 langues dans le monde, mais près de la moitié sont menacées de disparition. La moitié de l'humanité parle l'une des vingt-cinq langues les plus répandues." },
  // ---------- Technologie ----------
  { id: "tec-1", theme: "tech", title: "Le premier « bug » était un insecte",
    text: "En 1947, l'équipe de Grace Hopper trouve un vrai papillon de nuit coincé dans un relais de l'ordinateur Harvard Mark II. Ils le collent dans leur journal avec la mention « premier cas réel de bug trouvé »." },
  { id: "tec-2", theme: "tech", title: "Le premier SMS",
    text: "Le 3 décembre 1992, l'ingénieur Neil Papworth envoie depuis un ordinateur le tout premier SMS à un téléphone portable. Son message : « Merry Christmas »." },
  { id: "tec-3", theme: "tech", title: "Le premier site web existe encore",
    text: "Tim Berners-Lee invente le Web au CERN, près de Genève. Le tout premier site web est mis en ligne en 1991 pour expliquer… ce qu'est le Web. Le CERN le garde consultable aujourd'hui." },
  { id: "tec-4", theme: "tech", title: "Ton téléphone bat Apollo 11",
    text: "L'ordinateur de guidage d'Apollo 11 disposait d'environ 4 Ko de mémoire vive. Un smartphone actuel en a des millions de fois plus, et une puissance de calcul incomparablement supérieure." },
  { id: "tec-5", theme: "tech", title: "« Wi-Fi » ne veut rien dire",
    text: "Contrairement à une idée reçue, Wi-Fi n'est pas l'abréviation de « Wireless Fidelity ». C'est un nom de marque inventé en 1999 par une agence de communication, parce qu'il sonnait bien." },
  { id: "tec-6", theme: "tech", title: "Le QR code vient de l'automobile",
    text: "Le QR code a été inventé en 1994 au Japon par Denso Wave, une filiale de Toyota, pour suivre les pièces sur les chaînes de montage. « QR » signifie « Quick Response » : réponse rapide." },
  { id: "tec-7", theme: "tech", title: "ENIAC, l'ordinateur de 30 tonnes",
    text: "Achevé en 1945 aux États-Unis, l'ENIAC est l'un des premiers ordinateurs électroniques. Il pesait environ 30 tonnes, occupait une grande salle et contenait près de 18 000 tubes à vide." },
  { id: "tec-8", theme: "tech", title: "Pourquoi le clavier est-il mélangé ?",
    text: "La disposition QWERTY (et sa cousine française AZERTY) a été conçue pour les machines à écrire au XIXe siècle. Elle séparait notamment des lettres fréquentes pour éviter que les tiges métalliques ne se coincent." },
  { id: "tec-9", theme: "tech", title: "ChatGPT, un record d'adoption",
    text: "Lancé fin novembre 2022, ChatGPT aurait atteint 100 millions d'utilisateurs en environ deux mois, un record à l'époque. Il a fait entrer l'intelligence artificielle générative dans le quotidien du grand public." },
  { id: "tec-10", theme: "tech", title: "L'Europe encadre l'IA",
    text: "Adopté en 2024, le règlement européen sur l'intelligence artificielle (AI Act) est le premier grand cadre légal au monde sur l'IA. Il classe les usages selon leur niveau de risque et interdit certaines pratiques, comme la notation sociale des citoyens." },
  { id: "tec-11", theme: "tech", title: "Le premier iPhone",
    text: "Steve Jobs a présenté le premier iPhone le 9 janvier 2007. Il n'avait ni App Store ni appareil photo frontal. L'App Store n'est arrivé qu'un an plus tard, en 2008." },
  { id: "tec-12", theme: "tech", title: "Le Minitel, l'internet français",
    text: "Bien avant le Web, la France avait le Minitel, lancé au début des années 1980. On pouvait y consulter l'annuaire, réserver un train ou discuter. Il a été définitivement arrêté le 30 juin 2012." },
  { id: "tec-13", theme: "tech", title: "Internet passe sous la mer",
    text: "Plus de 95 % du trafic internet entre les continents passe par des câbles posés au fond des océans, et non par des satellites. Il en existe plusieurs centaines, longs au total de plus d'un million de kilomètres." },
  { id: "tec-14", theme: "tech", title: "Le mot de passe le plus courant",
    text: "Année après année, les classements des mots de passe les plus utilisés placent « 123456 » en tête. Il se craque en moins d'une seconde. Un long mot de passe unique ou une phrase est bien plus sûr." },
  { id: "tec-15", theme: "tech", title: "La loi de Moore",
    text: "En 1965, Gordon Moore, cofondateur d'Intel, prédit que le nombre de transistors sur une puce doublera régulièrement, environ tous les deux ans. Les puces actuelles en contiennent des dizaines de milliards." },
  // ---------- Psychologie ----------
  { id: "psy-1", theme: "psycho", title: "La courbe de l'oubli",
    text: "Au XIXe siècle, Hermann Ebbinghaus a montré qu'on oublie très vite ce qu'on vient d'apprendre, surtout les premiers jours. La parade : réviser à intervalles de plus en plus espacés." },
  { id: "psy-2", theme: "psycho", title: "On se souvient des tâches inachevées",
    text: "L'effet Zeigarnik décrit notre tendance à mieux nous souvenir des tâches interrompues que des tâches terminées. Une tâche en suspens reste « ouverte » dans notre esprit." },
  { id: "psy-3", theme: "psycho", title: "Le sommeil range la mémoire",
    text: "Pendant le sommeil, le cerveau rejoue et consolide ce qu'on a appris dans la journée. Dormir après avoir appris améliore nettement la mémorisation." },
  { id: "psy-4", theme: "psycho", title: "66 jours pour une habitude",
    text: "Une étude de l'University College de Londres (2009) a montré qu'il faut en moyenne 66 jours pour qu'un nouveau comportement devienne automatique, avec des écarts de 18 à 254 jours selon les personnes." },
  { id: "psy-5", theme: "psycho", title: "L'effet Dunning-Kruger",
    text: "Les personnes les moins compétentes dans un domaine ont tendance à surestimer leur niveau, faute de savoir ce qu'elles ignorent. À l'inverse, les experts se sous-estiment parfois." },
  { id: "psy-6", theme: "psycho", title: "Le biais de confirmation",
    text: "Nous avons tendance à chercher, retenir et croire surtout les informations qui confirment ce que nous pensons déjà, et à ignorer celles qui les contredisent." },
  { id: "psy-7", theme: "psycho", title: "On aime ce qu'on connaît",
    text: "L'effet de simple exposition, étudié par Robert Zajonc, montre qu'on apprécie davantage un visage, un mot ou une musique simplement parce qu'on l'a déjà vu ou entendu plusieurs fois." },
  { id: "psy-8", theme: "psycho", title: "Un placebo peut marcher… même avoué",
    text: "Plusieurs études ont montré que des patients peuvent ressentir un soulagement même en sachant qu'ils prennent un placebo, c'est-à-dire une pilule sans principe actif. Le rituel du soin compte aussi." },
  { id: "psy-9", theme: "psycho", title: "L'expérience de Milgram",
    text: "Dans les années 1960, Stanley Milgram demande à des volontaires d'envoyer des décharges électriques (fictives) à un inconnu. Environ 65 % vont jusqu'au maximum, simplement parce qu'une figure d'autorité le leur demande." },
  { id: "psy-10", theme: "psycho", title: "Notre mémoire immédiate est limitée",
    text: "On a longtemps dit qu'on pouvait retenir « 7 éléments, plus ou moins 2 » à la fois. Les recherches récentes estiment plutôt notre mémoire de travail à environ 4 éléments. D'où l'intérêt de regrouper les infos, comme un numéro de téléphone par paires." },
  { id: "psy-11", theme: "psycho", title: "L'effet du témoin",
    text: "Plus il y a de témoins d'une situation d'urgence, moins chacun a tendance à intervenir : on pense que quelqu'un d'autre va agir. Pour obtenir de l'aide, mieux vaut désigner une personne précise." },
  { id: "psy-12", theme: "psycho", title: "La règle du pic et de la fin",
    text: "Selon le psychologue Daniel Kahneman, on juge une expérience surtout d'après son moment le plus intense et sa fin, plutôt que sa durée totale. Une bonne fin peut sauver le souvenir d'un moment moyen." },
  { id: "psy-13", theme: "psycho", title: "Le multitâche est un mythe",
    text: "Le cerveau ne fait pas vraiment deux tâches complexes à la fois : il alterne rapidement entre elles. Chaque bascule coûte du temps et de l'attention, ce qui augmente les erreurs." },
  { id: "psy-14", theme: "psycho", title: "Perdre fait plus mal que gagner",
    text: "Perdre 100 € nous affecte environ deux fois plus que gagner 100 € ne nous réjouit. C'est l'aversion à la perte, mise en évidence par Kahneman et Tversky. Elle explique beaucoup de nos choix financiers." },
  { id: "psy-15", theme: "psycho", title: "Trop de choix tue le choix",
    text: "Dans une célèbre étude, un stand proposant 24 confitures attirait plus de monde, mais celui qui n'en proposait que 6 vendait beaucoup plus. Face à trop d'options, on hésite et on est souvent moins satisfait." },
  // ---------- Économie ----------
  { id: "eco-1", theme: "eco", title: "Les premières pièces de monnaie",
    text: "Les premières pièces connues ont été frappées en Lydie (dans l'actuelle Turquie) au VIIe siècle av. J.-C., dans un alliage naturel d'or et d'argent appelé électrum." },
  { id: "eco-2", theme: "eco", title: "Le billet de banque est chinois",
    text: "Les premiers billets de banque officiels sont apparus en Chine sous la dynastie Song, au XIe siècle. Plus légers que des sacs de pièces, ils facilitaient le commerce." },
  { id: "eco-3", theme: "eco", title: "Le record de l'hyperinflation",
    text: "En Hongrie, en 1946, les prix doublaient environ toutes les 15 heures. Le pays a imprimé un billet de 100 trillions (10²⁰) de pengő, le plus gros montant jamais imprimé." },
  { id: "eco-4", theme: "eco", title: "La règle de 72",
    text: "Pour savoir en combien d'années un placement double, divise 72 par son taux d'intérêt annuel. À 6 % par an, ton argent double en environ 12 ans grâce aux intérêts composés." },
  { id: "eco-5", theme: "eco", title: "Le Monopoly critiquait les monopoles",
    text: "L'ancêtre du Monopoly, « The Landlord's Game », a été créé en 1904 par Lizzie Magie pour dénoncer la concentration des richesses entre les mains des propriétaires." },
  { id: "eco-6", theme: "eco", title: "L'euro dans nos poches depuis 2002",
    text: "L'euro existe comme monnaie de compte depuis 1999, mais les pièces et billets ne sont arrivés dans les portefeuilles que le 1er janvier 2002, dans 12 pays." },
  { id: "eco-7", theme: "eco", title: "La banque vient d'un banc",
    text: "Le mot « banque » vient de l'italien « banca », le banc ou la table sur laquelle les changeurs de monnaie faisaient leurs affaires dans les villes italiennes du Moyen Âge." },
  { id: "eco-8", theme: "eco", title: "Le paradoxe de l'eau et du diamant",
    text: "L'eau est indispensable à la vie mais coûte presque rien, alors que le diamant est inutile pour survivre et coûte très cher. Adam Smith l'expliquait par la différence entre valeur d'usage et valeur d'échange ; on parle aujourd'hui de rareté." },
  { id: "eco-9", theme: "eco", title: "La Bulgarie passe à l'euro",
    text: "Le 1er janvier 2026, la Bulgarie a adopté l'euro, devenant le 21e pays de la zone euro, après la Croatie en 2023. Près de 350 millions d'Européens utilisent désormais la monnaie unique." },
  { id: "eco-10", theme: "eco", title: "Le PIB, une invention récente",
    text: "Le produit intérieur brut (PIB), qui mesure la richesse produite par un pays, a été conçu dans les années 1930 par l'économiste Simon Kuznets. Lui-même prévenait qu'il ne mesure pas le bien-être d'une nation." },
  { id: "eco-11", theme: "eco", title: "La première Bourse",
    text: "La première Bourse moderne est née à Amsterdam en 1602, avec la Compagnie néerlandaise des Indes orientales. Ce fut la première entreprise à vendre ses actions au public." },
  { id: "eco-12", theme: "eco", title: "Le mystère Satoshi Nakamoto",
    text: "Le Bitcoin a été créé en 2008-2009 par une personne ou un groupe se faisant appeler Satoshi Nakamoto, dont l'identité reste inconnue. Le nombre de bitcoins est limité par le code à 21 millions." },
  { id: "eco-13", theme: "eco", title: "La TVA est française",
    text: "La taxe sur la valeur ajoutée (TVA) a été inventée en France en 1954 par le haut fonctionnaire Maurice Lauré. Elle est aujourd'hui appliquée dans plus de 170 pays et reste la première recette fiscale de l'État français." },
  { id: "eco-14", theme: "eco", title: "Pourquoi viser 2 % d'inflation ?",
    text: "La Banque centrale européenne vise une inflation d'environ 2 % par an. Une légère hausse des prix est jugée saine, alors qu'une baisse générale (la déflation) pousse à reporter ses achats et peut freiner l'économie." },
  { id: "eco-15", theme: "eco", title: "L'indice Big Mac",
    text: "Depuis 1986, le magazine The Economist compare le prix d'un Big Mac dans différents pays pour estimer, avec humour, si une monnaie est surévaluée ou sous-évaluée. C'est une illustration simple du pouvoir d'achat." },
  // ---------- Cuisine ----------
  { id: "cui-1", theme: "cuisine", title: "Le miel ne se périme (presque) jamais",
    text: "Très sucré, pauvre en eau et légèrement acide, le miel empêche les bactéries de se développer. Des archéologues ont retrouvé dans des tombes égyptiennes des pots de miel vieux de plusieurs milliers d'années." },
  { id: "cui-2", theme: "cuisine", title: "Les carottes étaient violettes",
    text: "Les premières carottes cultivées étaient surtout violettes ou jaunes. La carotte orange s'est imposée grâce à des sélections menées aux Pays-Bas vers le XVIIe siècle." },
  { id: "cui-3", theme: "cuisine", title: "La tomate est un fruit",
    text: "En botanique, un fruit est la partie de la plante qui contient les graines et provient de la fleur. La tomate, comme le concombre ou l'aubergine, est donc un fruit, même si on la cuisine comme un légume." },
  { id: "cui-4", theme: "cuisine", title: "Piment : buvez du lait, pas de l'eau",
    text: "La brûlure du piment vient de la capsaïcine, qui active les capteurs de chaleur de la langue. Elle ne se dissout pas dans l'eau, mais dans les graisses : le lait ou le yaourt soulagent bien mieux." },
  { id: "cui-5", theme: "cuisine", title: "Le croissant est autrichien",
    text: "Le croissant descend du « kipferl » viennois. Il a été popularisé en France vers 1838 par la boulangerie viennoise d'August Zang à Paris, avant que les boulangers français ne l'adaptent en pâte feuilletée." },
  { id: "cui-6", theme: "cuisine", title: "La réaction de Maillard",
    text: "La croûte du pain, le goût du steak grillé ou du café torréfié viennent de la réaction de Maillard : à haute température, les sucres et les protéines réagissent et créent des centaines d'arômes." },
  { id: "cui-7", theme: "cuisine", title: "La cacahuète n'est pas une noix",
    text: "Malgré son nom anglais « peanut », la cacahuète est une légumineuse, de la même famille que les pois et les lentilles. Ses gousses mûrissent sous terre." },
  { id: "cui-8", theme: "cuisine", title: "Pourquoi l'oignon fait pleurer",
    text: "En coupant un oignon, on brise ses cellules, ce qui libère un gaz soufré irritant. Au contact de l'œil, il déclenche les larmes. Un couteau bien aiguisé et un oignon froid limitent les dégâts." },
  { id: "cui-9", theme: "cuisine", title: "La baguette à l'UNESCO",
    text: "En 2022, les savoir-faire artisanaux et la culture de la baguette ont été inscrits au patrimoine culturel immatériel de l'UNESCO. Il s'en vend des millions chaque jour en France." },
  { id: "cui-10", theme: "cuisine", title: "Le repas gastronomique des Français",
    text: "Depuis 2010, le « repas gastronomique des Français » est inscrit au patrimoine immatériel de l'UNESCO. Ce n'est pas un plat qui est protégé, mais un rituel : apéritif, entrée, plat, fromage, dessert, et l'art de bien les accorder." },
  { id: "cui-11", theme: "cuisine", title: "Le safran, épice la plus chère",
    text: "Le safran est fait des pistils de la fleur de crocus, cueillis à la main. Il faut environ 150 000 fleurs pour obtenir un seul kilo, ce qui en fait l'épice la plus chère du monde." },
  { id: "cui-12", theme: "cuisine", title: "La vanille et Edmond Albius",
    text: "La vanille est le fruit d'une orchidée. Hors du Mexique, elle ne donnait presque pas de fruits jusqu'à ce qu'en 1841, à La Réunion, Edmond Albius, un esclave de 12 ans, invente une méthode simple de pollinisation à la main, toujours utilisée." },
  { id: "cui-13", theme: "cuisine", title: "Le ketchup, un ancien remède",
    text: "Dans les années 1830, aux États-Unis, la sauce tomate était vendue sous forme de pilules présentées comme un remède contre l'indigestion. Le ketchup tel qu'on le connaît s'est imposé plus tard, à la fin du XIXe siècle." },
  { id: "cui-14", theme: "cuisine", title: "Marco Polo n'a pas rapporté les pâtes",
    text: "On raconte que Marco Polo aurait ramené les pâtes de Chine. C'est une légende : des pâtes sèches existaient déjà en Italie, notamment en Sicile, avant son retour en 1295." },
  { id: "cui-15", theme: "cuisine", title: "La fraise n'est pas une baie",
    text: "En botanique, la fraise n'est pas une baie : ses vrais fruits sont les petits « grains » sur sa peau, les akènes. À l'inverse, la banane, la tomate et même l'avocat sont botaniquement des baies." },
  // ---------- Sport ----------
  { id: "spo-1", theme: "sport", title: "Pourquoi 42,195 km ?",
    text: "Le marathon mesure 42,195 km depuis les Jeux olympiques de Londres en 1908 : le parcours partait du château de Windsor et devait arriver devant la loge royale du stade. Cette distance est devenue officielle en 1921." },
  { id: "spo-2", theme: "sport", title: "Paris, trois fois olympique",
    text: "Paris a accueilli les Jeux olympiques d'été en 1900, 1924 et 2024. Elle partage ce record avec Londres. En 1900, les femmes ont participé aux Jeux pour la première fois." },
  { id: "spo-3", theme: "sport", title: "Léon Marchand, quatre fois en or",
    text: "Aux Jeux de Paris 2024, le nageur Léon Marchand a remporté quatre médailles d'or individuelles (200 m papillon, 200 m brasse, 200 m et 400 m quatre nages), en plus d'un bronze en relais." },
  { id: "spo-4", theme: "sport", title: "Le breaking aux Jeux",
    text: "Le breaking, ou breakdance, a fait ses débuts olympiques à Paris 2024. Les danseurs, appelés b-boys et b-girls, s'affrontaient en battles improvisées sur la musique d'un DJ." },
  { id: "spo-5", theme: "sport", title: "Une Coupe du monde à 48 équipes",
    text: "La Coupe du monde de football 2026, organisée par les États-Unis, le Canada et le Mexique, a été la première à réunir 48 équipes, contre 32 auparavant, et la première organisée par trois pays." },
  { id: "spo-6", theme: "sport", title: "9,58 secondes",
    text: "Le record du monde du 100 m appartient à Usain Bolt : 9,58 secondes, réalisé à Berlin en 2009. À son pic, le Jamaïcain dépassait les 44 km/h." },
  { id: "spo-7", theme: "sport", title: "Le Tour de France, un coup de pub",
    text: "Le Tour de France a été créé en 1903 par le journal L'Auto pour augmenter ses ventes. Le maillot jaune, apparu en 1919, reprend la couleur du papier sur lequel le journal était imprimé." },
  { id: "spo-8", theme: "sport", title: "« Tenez ! »",
    text: "Le mot tennis viendrait du français « Tenez ! », que lançaient les joueurs de jeu de paume en servant. Ce jeu, ancêtre du tennis, était très populaire à la cour de France." },
  { id: "spo-9", theme: "sport", title: "Roland Garros était aviateur",
    text: "Le stade Roland-Garros porte le nom d'un aviateur, pas d'un joueur de tennis. En 1913, Roland Garros est le premier à traverser la Méditerranée en avion, de Fréjus à Bizerte, en Tunisie." },
  { id: "spo-10", theme: "sport", title: "Le basket et ses paniers à pêches",
    text: "En 1891, aux États-Unis, le professeur canadien James Naismith invente le basket pour occuper ses élèves en hiver. Les premiers paniers étaient de vrais paniers à pêches : il fallait récupérer le ballon à chaque panier marqué." },
  { id: "spo-11", theme: "sport", title: "Michael Phelps, 28 médailles",
    text: "Le nageur américain Michael Phelps est l'athlète le plus médaillé de l'histoire des Jeux olympiques : 28 médailles, dont 23 en or, entre 2004 et 2016." },
  { id: "spo-12", theme: "sport", title: "Du golf sur la Lune",
    text: "En 1971, lors de la mission Apollo 14, l'astronaute Alan Shepard a frappé deux balles de golf sur la Lune avec une tête de club fixée sur un outil. C'est le premier sport jamais pratiqué sur un autre astre." },
  { id: "spo-13", theme: "sport", title: "La légende du rugby",
    text: "Selon la légende, le rugby est né en 1823 dans l'école de la ville de Rugby, en Angleterre, quand un élève, William Webb Ellis, a pris le ballon à la main pendant un match de football. La Coupe du monde porte son nom." },
  { id: "spo-14", theme: "sport", title: "La première Coupe du monde de foot",
    text: "La toute première Coupe du monde de football a eu lieu en 1930 en Uruguay, qui l'a remportée. L'idée venait du Français Jules Rimet, alors président de la FIFA." },
  { id: "spo-15", theme: "sport", title: "Le Vendée Globe",
    text: "Le Vendée Globe est une course à la voile autour du monde, en solitaire, sans escale et sans assistance. Elle part des Sables-d'Olonne tous les quatre ans, et les meilleurs bouclent le tour en environ 75 à 80 jours." },
  // ---------- Cinéma & séries ----------
  { id: "cin-1", theme: "cinema", title: "La première séance de cinéma",
    text: "Le 28 décembre 1895, à Paris, les frères Lumière organisent la première projection publique et payante de leur cinématographe, au Salon indien du Grand Café. Une trentaine de spectateurs assistent à dix courts films." },
  { id: "cin-2", theme: "cinema", title: "Méliès, magicien du cinéma",
    text: "Ancien illusionniste, Georges Méliès invente de nombreux effets spéciaux. Son « Voyage dans la Lune » (1902), avec la fusée plantée dans l'œil de la Lune, est l'une des images les plus célèbres du cinéma." },
  { id: "cin-3", theme: "cinema", title: "Le premier grand film parlant",
    text: "« Le Chanteur de jazz », sorti en 1927, est considéré comme le premier long métrage parlant à succès. En quelques années, le cinéma muet disparaît, et beaucoup d'acteurs à la voix peu adaptée perdent leur carrière." },
  { id: "cin-4", theme: "cinema", title: "Cannes, né après la guerre",
    text: "Le Festival de Cannes devait avoir lieu pour la première fois en septembre 1939, mais il a été annulé par la Seconde Guerre mondiale. La première édition s'est tenue en 1946. La Palme d'or existe depuis 1955." },
  { id: "cin-5", theme: "cinema", title: "La statuette des Oscars",
    text: "La statuette des Oscars mesure environ 34 cm et pèse près de 4 kg. Elle représente un chevalier tenant une épée, debout sur une bobine de film. Les gagnants n'ont pas le droit de la revendre." },
  { id: "cin-6", theme: "cinema", title: "L'Inde, premier producteur de films",
    text: "L'Inde produit plus de films que n'importe quel autre pays : souvent plus de 1 500 par an, en plusieurs langues. Bollywood, à Bombay, n'est qu'une partie de cette industrie." },
  { id: "cin-7", theme: "cinema", title: "Avatar, roi du box-office",
    text: "« Avatar » de James Cameron (2009) détient le record du box-office mondial, avec près de 2,9 milliards de dollars. « Avengers: Endgame » l'avait brièvement dépassé en 2019, avant qu'une ressortie en Chine ne rende la première place à Avatar." },
  { id: "cin-8", theme: "cinema", title: "Le cri de Wilhelm",
    text: "Un même cri enregistré en 1951 a été réutilisé dans des centaines de films, dont Star Wars et Indiana Jones. Surnommé « le cri de Wilhelm », c'est devenu un clin d'œil entre ingénieurs du son." },
  { id: "cin-9", theme: "cinema", title: "Les César, nommés d'après un sculpteur",
    text: "Les César, récompenses du cinéma français créées en 1976, portent le nom du sculpteur César, auteur de la statuette. Elle représente une compression de métal, sa technique signature." },
  { id: "cin-10", theme: "cinema", title: "Squid Game, phénomène mondial",
    text: "Sortie en 2021, la série sud-coréenne « Squid Game » est devenue en quelques semaines la série la plus regardée de l'histoire de Netflix à ce moment-là, alors qu'elle avait été refusée par des studios pendant près de dix ans." },
  { id: "cin-11", theme: "cinema", title: "Hitchcock sans Oscar",
    text: "Alfred Hitchcock, le « maître du suspense », n'a jamais remporté l'Oscar du meilleur réalisateur, malgré cinq nominations. Il a seulement reçu un prix honorifique en 1968." },
  { id: "cin-12", theme: "cinema", title: "Le record des Ch'tis",
    text: "Avec plus de 20 millions d'entrées en 2008, « Bienvenue chez les Ch'tis » de Dany Boon est le film français le plus vu en France. Seul « Titanic » a fait mieux dans les salles françaises." },
  { id: "cin-13", theme: "cinema", title: "24 images par seconde",
    text: "Au cinéma, une seconde de film est composée de 24 images fixes. Notre cerveau les fusionne et perçoit un mouvement continu. Cette norme s'est imposée avec l'arrivée du parlant, à la fin des années 1920." },
  { id: "cin-14", theme: "cinema", title: "Miyazaki, deux Oscars",
    text: "Le réalisateur japonais Hayao Miyazaki a remporté l'Oscar du meilleur film d'animation en 2003 pour « Le Voyage de Chihiro », puis un second en 2024 pour « Le Garçon et le Héron »." },
  { id: "cin-15", theme: "cinema", title: "La légende du train qui fonce",
    text: "On raconte que lors des premières projections de « L'Arrivée d'un train en gare de La Ciotat » des frères Lumière, les spectateurs ont fui de peur. Les historiens pensent que c'est très exagéré, voire une légende." },
  // ---------- Musique ----------
  { id: "mus-1", theme: "musique", title: "Mozart, compositeur à 5 ans",
    text: "Wolfgang Amadeus Mozart compose ses premières pièces vers 5 ans. Mort à 35 ans, il laisse plus de 600 œuvres, dont des opéras, des symphonies et des concertos encore joués partout." },
  { id: "mus-2", theme: "musique", title: "La Marseillaise est née à Strasbourg",
    text: "La Marseillaise a été composée en 1792 à Strasbourg par Rouget de Lisle, pour l'armée du Rhin. Elle doit son nom aux soldats marseillais qui l'ont chantée en arrivant à Paris. Elle devient l'hymne national en 1795." },
  { id: "mus-3", theme: "musique", title: "Le la à 440 Hz",
    text: "Pour que les orchestres du monde entier s'accordent, la note la de référence a été fixée à 440 vibrations par seconde (440 Hz). C'est le son du diapason et de la tonalité d'accordage des musiciens." },
  { id: "mus-4", theme: "musique", title: "Happy Birthday était protégé",
    text: "La chanson « Happy Birthday to You » a longtemps été soumise à des droits d'auteur : les films devaient payer pour la diffuser. En 2016, après un procès, elle est entrée dans le domaine public aux États-Unis." },
  { id: "mus-5", theme: "musique", title: "Le retour du vinyle",
    text: "Aux États-Unis, en 2022, il s'est vendu plus de disques vinyles que de CD, une première depuis les années 1980. Le vinyle séduit pour son son, mais aussi pour l'objet et ses pochettes." },
  { id: "mus-6", theme: "musique", title: "La Fête de la musique",
    text: "Créée en France en 1982, la Fête de la musique a lieu chaque 21 juin, jour du solstice d'été. Le principe : tout le monde peut jouer gratuitement dans la rue. Elle est aujourd'hui célébrée dans plus de 120 pays." },
  { id: "mus-7", theme: "musique", title: "Piano veut dire « doux »",
    text: "Le piano s'appelait à l'origine « pianoforte », « doux-fort » en italien. Contrairement au clavecin, il permet de jouer doucement ou fort selon la force avec laquelle on frappe les touches." },
  { id: "mus-8", theme: "musique", title: "Daft Punk, la French Touch",
    text: "Le duo français Daft Punk, formé à Paris en 1993, a popularisé la musique électronique française dans le monde entier. Toujours cachés sous leurs casques de robots, ils se sont séparés en 2021." },
  { id: "mus-9", theme: "musique", title: "Le rap est né dans le Bronx",
    text: "Le hip-hop est né dans les années 1970 dans le Bronx, à New York, lors de fêtes de quartier où des DJ comme Kool Herc faisaient tourner les passages rythmés des disques. Des MC se sont mis à rimer par-dessus." },
  { id: "mus-10", theme: "musique", title: "Bohemian Rhapsody, sans refrain",
    text: "Sortie en 1975, « Bohemian Rhapsody » de Queen dure près de 6 minutes, mélange ballade, opéra et hard rock, et n'a pas de refrain. Les maisons de disques la jugeaient trop longue pour la radio, mais elle est devenue un immense succès." },
  { id: "mus-11", theme: "musique", title: "Les frissons musicaux",
    text: "Si une musique te donne des frissons, c'est que ton cerveau libère de la dopamine, la molécule du plaisir, comme pour la nourriture ou les récompenses. Ce pic arrive souvent juste avant un moment attendu du morceau." },
  { id: "mus-12", theme: "musique", title: "Spotify est suédois",
    text: "Spotify a été fondé en 2006 à Stockholm, en Suède, pour lutter contre le piratage en proposant mieux que lui : écouter toute la musique légalement et facilement. Il est devenu le premier service de streaming musical au monde." },
  { id: "mus-13", theme: "musique", title: "Le Boléro de Ravel",
    text: "Le Boléro de Maurice Ravel (1928) répète la même mélodie pendant environ 15 minutes, avec un seul crescendo. Ravel lui-même le décrivait comme « un tissu orchestral sans musique ». C'est pourtant l'une des œuvres classiques les plus jouées au monde." },
  { id: "mus-14", theme: "musique", title: "Un orchestre symphonique",
    text: "Un orchestre symphonique compte en général entre 80 et 100 musiciens, répartis en quatre familles : les cordes, les bois, les cuivres et les percussions. Les cordes, devant le chef, sont les plus nombreuses." },
  { id: "mus-15", theme: "musique", title: "Le ver d'oreille",
    text: "Une chanson qui tourne en boucle dans la tête s'appelle un « ver d'oreille ». Cela touche presque tout le monde. Les mélodies simples et répétitives sont les plus coupables. Mâcher un chewing-gum aiderait à s'en débarrasser." },
  // ---------- Littérature ----------
  { id: "lit-1", theme: "litterature", title: "Le Petit Prince, traduit partout",
    text: "« Le Petit Prince » d'Antoine de Saint-Exupéry, publié en 1943, a été traduit dans plus de 500 langues et dialectes. C'est l'un des livres les plus traduits au monde." },
  { id: "lit-2", theme: "litterature", title: "Les funérailles de Victor Hugo",
    text: "À la mort de Victor Hugo en 1885, environ deux millions de personnes assistent à ses funérailles nationales à Paris. Il est ensuite inhumé au Panthéon." },
  { id: "lit-3", theme: "litterature", title: "Hugo contre la peine de mort",
    text: "Victor Hugo s'est battu toute sa vie contre la peine de mort, notamment dans « Le Dernier Jour d'un condamné » (1829). La France ne l'abolira qu'en 1981, près d'un siècle après sa mort." },
  { id: "lit-4", theme: "litterature", title: "Molière, mort après la scène",
    text: "En 1673, Molière est pris d'un malaise sur scène en jouant « Le Malade imaginaire ». Il termine la représentation et meurt quelques heures plus tard. On parle encore de la « langue de Molière » pour désigner le français." },
  { id: "lit-5", theme: "litterature", title: "Don Quichotte, premier roman moderne",
    text: "Publié en 1605 par l'Espagnol Cervantès, « Don Quichotte » raconte un homme qui se prend pour un chevalier et attaque des moulins à vent qu'il croit être des géants. Il est souvent considéré comme le premier roman moderne." },
  { id: "lit-6", theme: "litterature", title: "Le Goncourt rapporte 10 €",
    text: "Le prix Goncourt, le plus prestigieux prix littéraire français, est accompagné d'un chèque symbolique de 10 €. Mais il fait vendre des centaines de milliers d'exemplaires du livre récompensé." },
  { id: "lit-7", theme: "litterature", title: "Harry Potter, refusé une douzaine de fois",
    text: "Le premier manuscrit d'Harry Potter de J. K. Rowling a été refusé par une douzaine d'éditeurs avant d'être accepté en 1996. La saga s'est depuis vendue à plus de 600 millions d'exemplaires." },
  { id: "lit-8", theme: "litterature", title: "Agatha Christie, reine des ventes",
    text: "Agatha Christie est l'autrice de romans la plus vendue de l'histoire, avec environ 2 milliards d'exemplaires. Sa pièce « La Souricière » est jouée sans interruption à Londres depuis 1952." },
  { id: "lit-9", theme: "litterature", title: "Le mot « utopie »",
    text: "Le mot utopie a été inventé en 1516 par l'Anglais Thomas More, pour le titre de son livre décrivant une société idéale. Il vient du grec et signifie « en aucun lieu »." },
  { id: "lit-10", theme: "litterature", title: "Jules Verne, visionnaire",
    text: "Jules Verne, auteur de « Vingt mille lieues sous les mers » et du « Tour du monde en 80 jours », est l'un des écrivains les plus traduits au monde. Il a imaginé des sous-marins électriques et des voyages vers la Lune bien avant qu'ils existent." },
  { id: "lit-11", theme: "litterature", title: "Le plus long roman",
    text: "« À la recherche du temps perdu » de Marcel Proust est cité par le Guinness comme le plus long roman jamais publié, avec environ 9,6 millions de caractères. C'est là qu'apparaît la célèbre madeleine qui fait ressurgir des souvenirs." },
  { id: "lit-12", theme: "litterature", title: "Annie Ernaux, Nobel 2022",
    text: "En 2022, Annie Ernaux est devenue la première écrivaine française à recevoir le prix Nobel de littérature. Ses livres mêlent souvenirs personnels et histoire de la société." },
  { id: "lit-13", theme: "litterature", title: "Aladdin n'était pas dans les Mille et Une Nuits",
    text: "Les histoires d'Aladdin et d'Ali Baba ne figurent dans aucun manuscrit arabe ancien connu des « Mille et Une Nuits ». Elles ont été ajoutées au XVIIIe siècle par le traducteur français Antoine Galland, qui les tenait d'un conteur syrien." },
  { id: "lit-14", theme: "litterature", title: "1984 et Big Brother",
    text: "Dans « 1984 », publié en 1949, George Orwell décrit une société surveillée en permanence par « Big Brother ». Le roman a donné des mots courants comme « big brother » ou « novlangue »." },
  { id: "lit-15", theme: "litterature", title: "Shakespeare, inventeur de mots",
    text: "William Shakespeare a inventé ou popularisé des centaines de mots et d'expressions anglaises encore utilisés aujourd'hui. On lui attribue près de 40 pièces de théâtre, dont « Roméo et Juliette » et « Hamlet »." },
  // ---------- Philosophie ----------
  { id: "phi-1", theme: "philo", title: "Socrate n'a rien écrit",
    text: "Socrate, l'un des pères de la philosophie, n'a laissé aucun écrit. On le connaît surtout par les dialogues de son élève Platon. Sa méthode : poser des questions pour faire réfléchir son interlocuteur." },
  { id: "phi-2", theme: "philo", title: "« Je pense, donc je suis »",
    text: "En 1637, René Descartes cherche une certitude absolue. Il peut douter de tout, sauf d'une chose : s'il doute, c'est qu'il pense, et s'il pense, c'est qu'il existe. D'où son célèbre « Je pense, donc je suis »." },
  { id: "phi-3", theme: "philo", title: "Le mythe de la caverne",
    text: "Platon imagine des prisonniers enchaînés dans une caverne, qui ne voient que des ombres sur un mur et les prennent pour la réalité. Le philosophe est celui qui sort de la caverne et découvre le monde réel." },
  { id: "phi-4", theme: "philo", title: "Épicure n'était pas un fêtard",
    text: "On associe l'épicurisme aux plaisirs de la table, mais Épicure prônait surtout des plaisirs simples et l'absence de souffrance. Pour lui, l'amitié, la réflexion et la modération mènent au bonheur." },
  { id: "phi-5", theme: "philo", title: "Ce qui dépend de nous",
    text: "Les stoïciens, comme Épictète ou Marc Aurèle, conseillent de distinguer ce qui dépend de nous (nos jugements, nos actions) de ce qui n'en dépend pas (la météo, l'avis des autres). Se concentrer sur le premier apporte la sérénité." },
  { id: "phi-6", theme: "philo", title: "Le rasoir d'Ockham",
    text: "Le rasoir d'Ockham, du nom d'un moine anglais du XIVe siècle, est un principe de bon sens : entre plusieurs explications, il faut préférer la plus simple, celle qui suppose le moins d'hypothèses." },
  { id: "phi-7", theme: "philo", title: "Le dilemme du tramway",
    text: "Un tramway fonce vers cinq personnes. En actionnant un levier, tu le dévies vers une voie où se trouve une seule personne. Le fais-tu ? Imaginé par Philippa Foot en 1967, ce dilemme sert aujourd'hui à réfléchir aux choix des voitures autonomes." },
  { id: "phi-8", theme: "philo", title: "Le bateau de Thésée",
    text: "Si l'on remplace, une par une, toutes les planches d'un bateau, est-ce encore le même bateau ? Ce paradoxe antique interroge l'identité : nos cellules se renouvelant sans cesse, sommes-nous toujours la même personne ?" },
  { id: "phi-9", theme: "philo", title: "Pascal, philosophe et inventeur",
    text: "Blaise Pascal, auteur de la phrase « Le cœur a ses raisons que la raison ne connaît point », était aussi un génie des sciences. À 19 ans, il invente la Pascaline, l'une des premières machines à calculer." },
  { id: "phi-10", theme: "philo", title: "« On ne naît pas femme »",
    text: "Dans « Le Deuxième Sexe » (1949), Simone de Beauvoir écrit : « On ne naît pas femme : on le devient. » Elle montre que beaucoup de rôles attribués aux femmes viennent de la société, et non de la nature." },
  { id: "phi-11", theme: "philo", title: "Sartre a refusé le Nobel",
    text: "En 1964, Jean-Paul Sartre refuse le prix Nobel de littérature. Il estimait qu'un écrivain ne doit pas se laisser transformer en institution. Il reste l'une des rares personnes à l'avoir refusé volontairement." },
  { id: "phi-12", theme: "philo", title: "L'impératif de Kant",
    text: "Pour Emmanuel Kant, une action est morale si l'on peut vouloir que tout le monde agisse de la même façon. Mentir, par exemple, est mal car si tout le monde mentait, plus personne ne pourrait se faire confiance." },
  { id: "phi-13", theme: "philo", title: "Imaginer Sisyphe heureux",
    text: "Dans la mythologie, Sisyphe est condamné à pousser un rocher en haut d'une montagne, qui redescend sans cesse. Pour Albert Camus, la vie peut sembler aussi absurde, mais « il faut imaginer Sisyphe heureux » : le sens naît de l'effort lui-même." },
  { id: "phi-14", theme: "philo", title: "Montaigne invente l'essai",
    text: "Avec ses « Essais » (1580), Michel de Montaigne invente un genre : réfléchir librement sur tous les sujets en partant de sa propre expérience. Sa devise : « Que sais-je ? »" },
  { id: "phi-15", theme: "philo", title: "Achille et la tortue",
    text: "Le philosophe grec Zénon affirme qu'Achille ne rattrapera jamais une tortue partie avant lui : chaque fois qu'il atteint sa position, elle a un peu avancé. Ce paradoxe a mis des siècles à être résolu par les mathématiques des séries infinies." },
  // ---------- Environnement ----------
  { id: "env-1", theme: "environnement", title: "2024, année record",
    text: "Selon le service européen Copernicus, 2024 a été l'année la plus chaude jamais mesurée, et la première dont la température moyenne a dépassé de plus de 1,5 °C celle de l'ère préindustrielle." },
  { id: "env-2", theme: "environnement", title: "L'accord de Paris",
    text: "Signé en 2015 lors de la COP21, l'accord de Paris engage presque tous les pays du monde à limiter le réchauffement « bien en dessous de 2 °C », et si possible à 1,5 °C, par rapport à l'ère préindustrielle." },
  { id: "env-3", theme: "environnement", title: "L'océan, bouclier du climat",
    text: "Les océans absorbent environ un quart du CO₂ émis par les activités humaines et plus de 90 % de l'excès de chaleur lié au réchauffement. Mais cela les rend plus chauds et plus acides." },
  { id: "env-4", theme: "environnement", title: "Une respiration sur deux vient de l'océan",
    text: "Le phytoplancton, minuscules algues flottant dans les océans, produit environ la moitié de l'oxygène de la planète grâce à la photosynthèse. La forêt amazonienne, elle, consomme presque tout l'oxygène qu'elle produit." },
  { id: "env-5", theme: "environnement", title: "Le septième continent",
    text: "Dans le Pacifique Nord, les courants concentrent une immense zone de déchets plastiques, surtout des microplastiques. Surnommée le « septième continent », elle couvrirait environ 1,6 million de km², soit à peu près trois fois la France." },
  { id: "env-6", theme: "environnement", title: "Merci les pollinisateurs",
    text: "Environ trois quarts des principales cultures alimentaires dans le monde profitent, au moins en partie, de la pollinisation par les animaux, surtout les insectes comme les abeilles. Sans eux, fruits et légumes seraient bien plus rares." },
  { id: "env-7", theme: "environnement", title: "Le numérique pollue aussi",
    text: "Le numérique représente environ 3 à 4 % des émissions mondiales de gaz à effet de serre. La plus grande part vient de la fabrication des appareils : garder son téléphone plus longtemps est le geste le plus efficace." },
  { id: "env-8", theme: "environnement", title: "Le permafrost, bombe à carbone",
    text: "Le permafrost, sol gelé en permanence en Arctique, contient environ deux fois plus de carbone que l'atmosphère. En dégelant à cause du réchauffement, il peut en libérer une partie sous forme de CO₂ et de méthane." },
  { id: "env-9", theme: "environnement", title: "La forêt française a doublé",
    text: "La forêt française a presque doublé de surface depuis le milieu du XIXe siècle. Elle couvre aujourd'hui environ un tiers du territoire métropolitain, notamment grâce au reboisement et à l'abandon de terres agricoles." },
  { id: "env-10", theme: "environnement", title: "Le verre se recycle à l'infini",
    text: "Le verre peut être recyclé à l'infini sans perdre en qualité : une bouteille recyclée redevient une bouteille. Il faut juste la jeter dans le bon conteneur, sans bouchon." },
  { id: "env-11", theme: "environnement", title: "Le poids carbone de la viande",
    text: "Produire un kilo de bœuf émet en moyenne des dizaines de fois plus de gaz à effet de serre que produire un kilo de lentilles ou de pois. Les ruminants rejettent notamment du méthane en digérant." },
  { id: "env-12", theme: "environnement", title: "La Grande Barrière de corail",
    text: "Au large de l'Australie, la Grande Barrière de corail s'étend sur plus de 2 300 km. C'est la plus grande structure construite par des êtres vivants. Les vagues de chaleur marine provoquent régulièrement le blanchissement des coraux." },
  { id: "env-13", theme: "environnement", title: "La couche d'ozone se répare",
    text: "Grâce au protocole de Montréal de 1987, qui a interdit les gaz destructeurs comme les CFC, la couche d'ozone se reconstitue. Selon l'ONU, elle devrait retrouver son état de 1980 vers 2066 au-dessus de l'Antarctique." },
  { id: "env-14", theme: "environnement", title: "Le jour du dépassement",
    text: "Chaque année, le « jour du dépassement » marque la date où l'humanité a consommé tout ce que la planète peut régénérer en un an. Ces dernières années, il tombe fin juillet ou début août." },
  { id: "env-15", theme: "environnement", title: "Une bouteille plastique, des siècles",
    text: "Une bouteille en plastique peut mettre plusieurs centaines d'années à se fragmenter dans la nature, sans jamais vraiment disparaître : elle se transforme en microplastiques que l'on retrouve jusque dans les océans et notre organisme." },
  // ---------- Société & politique ----------
  { id: "soc-1", theme: "societe", title: "La Ve République",
    text: "La Constitution actuelle de la France date du 4 octobre 1958 et fonde la Ve République, voulue par le général de Gaulle. Elle donne un rôle central au président de la République." },
  { id: "soc-2", theme: "societe", title: "Du septennat au quinquennat",
    text: "Depuis un référendum de 2000, le président français est élu pour 5 ans, contre 7 auparavant. Le premier quinquennat a commencé en 2002. Depuis 2008, il ne peut pas faire plus de deux mandats consécutifs." },
  { id: "soc-3", theme: "societe", title: "577 députés, 348 sénateurs",
    text: "Le Parlement français a deux chambres : l'Assemblée nationale, avec 577 députés élus au suffrage direct, et le Sénat, avec 348 sénateurs élus par des élus locaux. Ensemble, ils votent les lois." },
  { id: "soc-4", theme: "societe", title: "L'ONU, 193 pays",
    text: "L'Organisation des Nations unies a été créée en 1945, après la Seconde Guerre mondiale, pour maintenir la paix. Elle compte 193 États membres, et son siège est à New York." },
  { id: "soc-5", theme: "societe", title: "L'Union européenne à 27",
    text: "Depuis la sortie du Royaume-Uni le 31 janvier 2020 (le Brexit), l'Union européenne compte 27 pays. Ses institutions principales siègent à Bruxelles, Strasbourg et Luxembourg." },
  { id: "soc-6", theme: "societe", title: "La Déclaration de 1789",
    text: "La Déclaration des droits de l'homme et du citoyen, adoptée le 26 août 1789, affirme que « les hommes naissent et demeurent libres et égaux en droits ». Elle fait toujours partie de la Constitution française." },
  { id: "soc-7", theme: "societe", title: "L'abolition de la peine de mort",
    text: "La France a aboli la peine de mort en 1981, sous l'impulsion du ministre de la Justice Robert Badinter. Aujourd'hui, plus des deux tiers des pays du monde l'ont abolie en droit ou en pratique." },
  { id: "soc-8", theme: "societe", title: "Léon XIV, premier pape américain",
    text: "En mai 2025, après la mort du pape François, le cardinal Robert Francis Prevost a été élu pape sous le nom de Léon XIV. Né à Chicago, il est le premier pape originaire des États-Unis." },
  { id: "soc-9", theme: "societe", title: "8 milliards d'humains",
    text: "Selon l'ONU, la population mondiale a dépassé les 8 milliards de personnes le 15 novembre 2022. Elle a doublé en moins de 50 ans et pourrait atteindre un pic d'environ 10 milliards dans les années 2080." },
  { id: "soc-10", theme: "societe", title: "Voter à 18 ans",
    text: "En France, la majorité et le droit de vote ont été abaissés de 21 à 18 ans en 1974, au début de la présidence de Valéry Giscard d'Estaing." },
  { id: "soc-11", theme: "societe", title: "La loi de 1905",
    text: "La loi du 9 décembre 1905 sépare les Églises et l'État en France : l'État garantit la liberté de culte, mais ne reconnaît ni ne finance aucune religion. C'est le cœur de la laïcité à la française." },
  { id: "soc-12", theme: "societe", title: "Les visages de Marianne",
    text: "Marianne, symbole de la République française, a parfois pris les traits de femmes célèbres pour ses bustes officiels, comme Brigitte Bardot, Catherine Deneuve ou Laetitia Casta." },
  { id: "soc-13", theme: "societe", title: "La Suisse ne vote qu'en 1971",
    text: "La Suisse pratique la démocratie directe : les citoyens votent plusieurs fois par an sur des sujets précis. Pourtant, les Suissesses n'ont obtenu le droit de vote au niveau fédéral qu'en 1971." },
  { id: "soc-14", theme: "societe", title: "L'IVG dans la Constitution",
    text: "En mars 2024, la France est devenue le premier pays au monde à inscrire explicitement dans sa Constitution la liberté de recourir à l'interruption volontaire de grossesse (IVG)." },
  { id: "soc-15", theme: "societe", title: "PACS et mariage pour tous",
    text: "En France, le PACS a été créé en 1999 pour permettre aux couples, de même sexe ou non, de s'unir civilement. Le mariage a été ouvert aux couples de même sexe en 2013." },
  // ---------- Mythologie ----------
  { id: "myt-1", theme: "mythologie", title: "Les jours de la semaine",
    text: "Nos jours viennent des astres et des dieux romains : lundi de la Lune, mardi de Mars, mercredi de Mercure, jeudi de Jupiter, vendredi de Vénus. Samedi vient du sabbat, et dimanche du « jour du Seigneur »." },
  { id: "myt-2", theme: "mythologie", title: "Le talon d'Achille",
    text: "Pour rendre son fils Achille invincible, la déesse Thétis l'a plongé dans le fleuve Styx en le tenant par le talon. Ce seul endroit, resté sec, était vulnérable : c'est là qu'une flèche l'a tué." },
  { id: "myt-3", theme: "mythologie", title: "La boîte de Pandore était une jarre",
    text: "Dans le mythe grec, Pandore ouvre un récipient qui libère tous les maux de l'humanité. Dans les textes anciens, c'était une jarre et non une boîte. Seule l'espérance est restée au fond." },
  { id: "myt-4", theme: "mythologie", title: "Les mois ont des dieux",
    text: "Janvier vient de Janus, dieu romain des commencements à deux visages. Mars vient du dieu de la guerre. Juillet et août honorent deux hommes : Jules César et l'empereur Auguste." },
  { id: "myt-5", theme: "mythologie", title: "Thor et Odin dans l'anglais",
    text: "En anglais, Thursday (jeudi) est le jour de Thor, dieu nordique du tonnerre, et Wednesday (mercredi) celui de Woden, autre nom d'Odin. Friday viendrait de Frigg, l'épouse d'Odin." },
  { id: "myt-6", theme: "mythologie", title: "Nike, déesse de la victoire",
    text: "La marque Nike porte le nom de la déesse grecque de la Victoire. Son logo, le « swoosh », évoquerait l'aile de la déesse. Il a été dessiné en 1971 par une étudiante, payée 35 dollars." },
  { id: "myt-7", theme: "mythologie", title: "La panique vient de Pan",
    text: "Pan, dieu grec des bergers mi-homme mi-bouc, était réputé pour pousser des cris terrifiants qui affolaient les troupeaux et les voyageurs. C'est de lui que vient le mot « panique »." },
  { id: "myt-8", theme: "mythologie", title: "Écho et Narcisse",
    text: "La nymphe Écho, punie par Héra, ne pouvait que répéter les derniers mots des autres. Amoureuse de Narcisse, elle fut rejetée. Narcisse, lui, tomba amoureux de son propre reflet, d'où le mot « narcissisme »." },
  { id: "myt-9", theme: "mythologie", title: "Le fil d'Ariane",
    text: "En Crète, le héros Thésée entre dans le labyrinthe pour tuer le Minotaure, mi-homme mi-taureau. Il retrouve la sortie grâce à une pelote de fil donnée par Ariane. Le « fil d'Ariane » désigne depuis un repère qui guide." },
  { id: "myt-10", theme: "mythologie", title: "Les douze travaux d'Hercule",
    text: "Héraclès, appelé Hercule par les Romains, doit accomplir douze travaux pour expier ses fautes : tuer le lion de Némée, l'hydre de Lerne, nettoyer les écuries d'Augias… D'où l'expression « un travail d'Hercule »." },
  { id: "myt-11", theme: "mythologie", title: "Le complexe d'Œdipe",
    text: "Dans la tragédie grecque, Œdipe tue son père et épouse sa mère sans le savoir. Freud s'est inspiré de ce mythe pour nommer le « complexe d'Œdipe », une étape du développement de l'enfant selon la psychanalyse." },
  { id: "myt-12", theme: "mythologie", title: "La pesée du cœur",
    text: "Dans l'Égypte ancienne, après la mort, le dieu Anubis à tête de chacal pesait le cœur du défunt face à la plume de Maât, déesse de la vérité. Un cœur trop lourd de fautes était dévoré par un monstre." },
  { id: "myt-13", theme: "mythologie", title: "Prométhée, voleur de feu",
    text: "Prométhée vola le feu aux dieux pour l'offrir aux humains. Pour le punir, Zeus l'enchaîna à un rocher où un aigle venait chaque jour dévorer son foie, qui repoussait chaque nuit." },
  { id: "myt-14", theme: "mythologie", title: "Le cheval de Troie",
    text: "Après dix ans de siège, les Grecs offrent aux Troyens un immense cheval de bois, où sont cachés des soldats. La nuit venue, ils ouvrent les portes de la ville. Le terme désigne aujourd'hui aussi un logiciel malveillant déguisé." },
  { id: "myt-15", theme: "mythologie", title: "Atlas porte le ciel",
    text: "Dans la mythologie grecque, le titan Atlas est condamné à porter la voûte céleste, et non la Terre comme on le croit souvent. Son nom a été donné aux recueils de cartes à partir du XVIe siècle." }
];
